bool isAlive = true;
float speed = 3.5f;

if (health <= 0)
{
    isAlive = false;
}
else if (health < 30)
{
    ShowWarning("Low health!");
}

for (int i = 0; i < enemies.Count; i++)
{
    enemies[i].Update();
}

int CalculateDamage(int baseDamage, float multiplier)
{
    return (int)(baseDamage * multiplier);
}
